===================================================================
--- index.html
+++ index.html
@@ -39,7 +39,53 @@
 <div id="intro"><div class="modal"><div class="eyebrow">// NEON DISTRICT · DUEL SIMULATION</div><h1>OWN THE<br><em>ARENA.</em></h1><div class="desc">One hero. One rival. No backup. Outplay the arena's most adaptive combat chassis in a high-speed 1v1.</div><div class="hero-pick"><div class="pick active" data-hero="vanguard"><strong>01 / VANGUARD</strong><span>ARMOR · AEGIS FIELD · PULSE CARBINE</span></div><div class="pick orange" data-hero="striker"><strong>02 / STRIKER</strong><span>SPEED · BLINK · ARC CANNON</span></div></div><div class="controls"><span><b>W A S D</b> move</span><span><b>MOUSE</b> aim</span><span><b>CLICK</b> fire</span><span><b>SHIFT</b> dash</span><span><b>E</b> ability</span><span><b>Q</b> overdrive</span></div><button class="startbtn" id="start">DEPLOY TO ARENA&nbsp; ↗</button><div class="footer-note">CLICK TO CAPTURE MOUSE · ESC TO RELEASE</div></div></div>
 <div id="result"><div class="modal" style="text-align:center"><div class="eyebrow">// SIMULATION COMPLETE</div><div class="result-title win" id="resultTitle">VICTORY</div><div class="desc" id="resultDesc" style="margin:0 auto 23px">Rival chassis disabled. Arena secured.</div><button class="startbtn" id="again">RUN IT BACK&nbsp; ↻</button></div></div>
 <script type="module">
 import * as THREE from 'https://unpkg.com/three@0.160.0/build/three.module.js';
-</script>
+
+// RIFT//DUEL — single-player arena combat simulation.
+const $ = (id) => document.getElementById(id);
+const scene = new THREE.Scene();
+scene.background = new THREE.Color(0x071116);
+scene.fog = new THREE.FogExp2(0x071116, 0.012);
+const camera = new THREE.PerspectiveCamera(66, innerWidth / innerHeight, 0.1, 150);
+const renderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: 'high-performance' });
+renderer.setSize(innerWidth, innerHeight); renderer.setPixelRatio(Math.min(devicePixelRatio, 1.7));
+renderer.shadowMap.enabled = true; renderer.shadowMap.type = THREE.PCFSoftShadowMap;
+renderer.outputColorSpace = THREE.SRGBColorSpace; renderer.toneMapping = THREE.ACESFilmicToneMapping; renderer.toneMappingExposure = 1.18;
+document.body.prepend(renderer.domElement);
+scene.add(new THREE.HemisphereLight(0x9beaff, 0x18202b, 1.55));
+const keyLight = new THREE.DirectionalLight(0xe5faff, 2.2); keyLight.position.set(-12, 24, -10); keyLight.castShadow = true;
+keyLight.shadow.mapSize.set(1024, 1024); keyLight.shadow.camera.left = -34; keyLight.shadow.camera.right = 34; keyLight.shadow.camera.top = 34; keyLight.shadow.camera.bottom = -34; scene.add(keyLight);
+const cyanLight = new THREE.PointLight(0x29cfff, 26, 22); cyanLight.position.set(-9, 3, 0); scene.add(cyanLight);
+const warmLight = new THREE.PointLight(0xff7540, 24, 22); warmLight.position.set(9, 3, 0); scene.add(warmLight);
+const mat = (color, roughness=.55, metalness=.25, emissive=0x000000, intensity=0) => new THREE.MeshStandardMaterial({ color, roughness, metalness, emissive, emissiveIntensity: intensity });
+const mats = {
+ floor: mat(0x111f27,.8,.55), dark: mat(0x0b151b,.45,.75), steel: mat(0x263943,.42,.7), pale: mat(0xb6ccd0,.35,.55), cyan: mat(0x50e5ff,.3,.45,0x0acfff,2), orange: mat(0xff8251,.32,.4,0xff481b,1.5), gold: mat(0xffb955,.35,.35,0xff892e,1), glass: mat(0x19404b,.2,.3,0x20bbd1,.7), white: mat(0xe6f8fa,.42,.25)
+};
+const boxGeo = new THREE.BoxGeometry(1,1,1);
+function meshBox(parent, material, pos, size, cast=true) { const m=new THREE.Mesh(boxGeo,material); m.position.set(...pos); m.scale.set(...size); m.castShadow=cast; m.receiveShadow=true; parent.add(m); return m; }
+function ring(radius,tube,color,y=0) { const m=new THREE.Mesh(new THREE.TorusGeometry(radius,tube,8,120),color); m.rotation.x=-Math.PI/2; m.position.y=y; scene.add(m); return m; }
+function createArena() {
+ const platform=new THREE.Mesh(new THREE.CylinderGeometry(29,30,1.25,12),mats.floor); platform.position.y=-.7; platform.receiveShadow=true; platform.castShadow=true; scene.add(platform);
+ const floor=new THREE.Mesh(new THREE.CircleGeometry(28.6,12),mats.floor); floor.rotation.x=-Math.PI/2; floor.position.y=-.065; floor.receiveShadow=true; scene.add(floor);
+ for(let r=5;r<=27;r+=5) ring(r,.035, r%10?mats.steel:mats.cyan,.006);
+ const outer=new THREE.Mesh(new THREE.TorusGeometry(29,.38,8,12),mats.dark); outer.rotation.x=-Math.PI/2; outer.position.y=-.12; scene.add(outer);
+ // Modular floor seams and luminous lane markers.
+ const lineMat=new THREE.LineBasicMaterial({color:0x29414a,transparent:true,opacity:.6});
+ for(let a=0;a<12;a++){const angle=a*Math.PI/6; const pts=[new THREE.Vector3(0,.012,0),new THREE.Vector3(28*Math.sin(angle),.012,28*Math.cos(angle))];scene.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts),lineMat));}
+ // Hexagonal arena anchors, beacon columns, and tactical cover.
+ const obstacles=[];
+ const cover=(x,z,w,d,h,accent)=>{const g=new THREE.Group();g.position.set(x,0,z);scene.add(g);meshBox(g,mats.dark,[0,h/2,0],[w,h,d]);meshBox(g,mats.steel,[0,h-.12,0],[w+.08,.16,d+.08]);meshBox(g,accent,[0,h-.28,d/2+.012],[w*.55,.08,.04],false);obstacles.push({x,z,r:Math.max(w,d)*.58});return g;};
+ cover(-8,-5,2.1,2.1,2.5,mats.cyan); cover(8,5,2.1,2.1,2.5,mats.orange);
+ cover(-8,6,2.8,1.5,1.6,mats.cyan); cover(8,-6,2.8,1.5,1.6,mats.orange);
+ cover(-2,1,1.2,2.4,1.5,mats.cyan); cover(2,-1,1.2,2.4,1.5,mats.orange);
+ for(let i=0;i<8;i++){const a=i*Math.PI/4;const x=Math.sin(a)*24,z=Math.cos(a)*24;const p=new THREE.Group();p.position.set(x,0,z);p.rotation.y=a;scene.add(p);meshBox(p,mats.dark,[0,2.4,0],[1.5,4.8,1.5]);meshBox(p,i%2?mats.orange:mats.cyan,[0,4.86,0],[1.56,.12,1.56],false);const strip=meshBox(p,i%2?mats.orange:mats.cyan,[0,2.5,.76],[.08,3.8,.05],false);strip.material=strip.material.clone();strip.material.emissiveIntensity=1.6;}
+ // Distant skyline silhouettes surround the fighting bowl.
+ for(let i=0;i<25;i++){const a=i*Math.PI*2/25;const r=39+(i%3)*2;const h=5+(i*7%11);const b=new THREE.Mesh(new THREE.BoxGeometry(3+(i%3),h,3),mats.dark);b.position.set(Math.sin(a)*r,h/2-1,Math.cos(a)*r);b.lookAt(0,h/2,0);scene.add(b);for(let y=1;y<h-1;y+=1.5){const win=new THREE.Mesh(new THREE.BoxGeometry(.09,.12,1.55),i%2?mats.cyan:mats.orange);win.position.set(Math.sin(a)*(r-1.6),y,Math.cos(a)*(r-1.6));win.rotation.y=a;scene.add(win);}}
+ // arena spawn plates
+ ring(3.2,.09,mats.cyan,.025);ring(3.2,.09,mats.orange,.025);
+ return obstacles;
+}
+const obstacles=createArena();
+
 </body>
 </html>

