const obstacles=createArena();
function makeHero(colorMat, isEnemy=false, striker=false) {
 const root=new THREE.Group(); scene.add(root);
 const torso=meshBox(root,mats.dark,[0,1.25,0],[.9,1.05,.48]);
 meshBox(root,colorMat,[0,1.48,.26],[.72,.47,.12]);
 meshBox(root,mats.steel,[0,1.85,0],[.72,.19,.5]);
 const head=new THREE.Group();head.position.set(0,2.1,0);root.add(head);
 const helm=new THREE.Mesh(new THREE.SphereGeometry(.38,12,10),mats.steel);helm.scale.set(1,.92,.9);helm.castShadow=true;head.add(helm);
 meshBox(head,colorMat,[0,-.02,.315],[.48,.13,.09],false);
 const eye=meshBox(head,isEnemy?mats.orange:mats.cyan,[0,-.02,.37],[.31,.045,.025],false);
 const armL=new THREE.Group();armL.position.set(-.58,1.6,0);root.add(armL);
 meshBox(armL,mats.steel,[0,-.31,0],[.32,.68,.38]);meshBox(armL,colorMat,[0,-.04,.04],[.4,.22,.42]);
 const armR=new THREE.Group();armR.position.set(.58,1.6,0);root.add(armR);
 meshBox(armR,mats.steel,[0,-.31,0],[.32,.68,.38]);meshBox(armR,colorMat,[0,-.04,.04],[.4,.22,.42]);
 const legL=new THREE.Group();legL.position.set(-.25,.78,0);root.add(legL);meshBox(legL,mats.dark,[0,-.25,0],[.34,.74,.43]);meshBox(legL,mats.steel,[0,-.6,.12],[.4,.18,.59]);
 const legR=new THREE.Group();legR.position.set(.25,.78,0);root.add(legR);meshBox(legR,mats.dark,[0,-.25,0],[.34,.74,.43]);meshBox(legR,mats.steel,[0,-.6,.12],[.4,.18,.59]);
 const gun=new THREE.Group();gun.position.set(.62,1.28,.25);root.add(gun);
 meshBox(gun,mats.dark,[0,0,.32],[.24,.22,.83]);meshBox(gun,colorMat,[0,.1,.36],[.16,.06,.65],false);meshBox(gun,mats.steel,[0,-.13,.05],[.16,.22,.18]);
 const muzzle=new THREE.Object3D();muzzle.position.set(0,0,.78);gun.add(muzzle);
 let shield=null;
 if(!striker){shield=new THREE.Mesh(new THREE.SphereGeometry(1,20,16),new THREE.MeshBasicMaterial({color:isEnemy?0xff844b:0x42dfff,transparent:true,opacity:.11,wireframe:true,depthWrite:false}));shield.scale.set(1.05,1.35,.8);shield.position.y=1.15;shield.visible=false;root.add(shield);}
 const point=new THREE.Mesh(new THREE.SphereGeometry(.52,10,8),new THREE.MeshBasicMaterial({visible:false}));point.position.y=1.28;root.add(point);
 return {root,head,armL,armR,legL,legR,gun,muzzle,shield,point, eye, torso};
}
const playerModel=makeHero(mats.cyan,false,false), enemyModel=makeHero(mats.orange,true,true);
const player={model:playerModel,pos:new THREE.Vector3(0,0,-13),vel:new THREE.Vector3(),hp:250,maxHp:250,ammo:24,alive:true,cdDash:0,cdAbility:0,charge:0,overdrive:0,shieldTime:0,invuln:0,score:0};
const enemy={model:enemyModel,pos:new THREE.Vector3(0,0,13),vel:new THREE.Vector3(),hp:200,maxHp:200,alive:true,shootTimer:1,strafe:1,change:0,dashCd:2,stun:0};
const raycaster=new THREE.Raycaster();raycaster.far=90;
const clock=new THREE.Clock();
const state={running:false,ended:false,hero:'vanguard',time:0,yaw:0,pitch:-.06,fire:false,lastShot:0,reloadTimer:0,keys:{},mouse:{x:0,y:0},stick:{x:0,y:0},lastDamage:0,toastTimer:0,shake:0};
const effects=[];
const tracerMat=new THREE.MeshBasicMaterial({color:0x72efff});
function tracer(a,b,color=0x75edff){const d=new THREE.Vector3().subVectors(b,a),line=new THREE.Mesh(new THREE.CylinderGeometry(.025,.025,d.length(),5),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.85}));line.position.copy(a).add(b).multiplyScalar(.5);line.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),d.normalize());scene.add(line);effects.push({object:line,time:.12,life:.12});}
function impact(pos,color=0x6deaff){const g=new THREE.Group();g.position.copy(pos);scene.add(g);for(let i=0;i<5;i++){const m=new THREE.Mesh(new THREE.SphereGeometry(.045,5,4),new THREE.MeshBasicMaterial({color,transparent:true}));m.position.set((Math.random()-.5)*.45,(Math.random()-.5)*.4,(Math.random()-.5)*.45);g.add(m);}effects.push({object:g,time:.22,life:.22});}
function announce(text){const n=$('notice');n.textContent=text;n.style.opacity='1';state.toastTimer=1.4;}
function setHp(who){const isPlayer=who===player;const pct=Math.max(0,who.hp/who.maxHp*100);$(isPlayer?'php':'ehp').style.width=pct+'%';$(isPlayer?'phptext':'ehptext').textContent=Math.ceil(who.hp);}
function updateHeroUI(){const striker=state.hero==='striker';$('pname').textContent=striker?'STRIKER':'VANGUARD';$('selfname').textContent=striker?'STRIKER':'VANGUARD';$('pclass').textContent=striker?'SKIRMISHER / 02':'FRONTLINE / 01';$('selfrole').textContent=striker?'MOBILITY SPECIALIST':'TACTICAL ASSAULT';$('portrait').textContent=striker?'S':'V';$('weapon').textContent=striker?'ARC CANNON':'PULSE CARBINE';$('abilityLabel').textContent=striker?'PHASE BLINK':'AEGIS';$('ammo').textContent=player.ammo;}
function activateHero(hero){state.hero=hero;const striker=hero==='striker';player.maxHp=striker?200:250;player.hp=player.maxHp;player.ammo=striker?18:24;player.charge=0;updateHeroUI();setHp(player);}
function setAbilityReady(id,ready){$(id).classList.toggle('ready',ready);$(id).classList.toggle('cooldown',!ready);}
function showEnd(win){state.ended=true;state.running=false;document.exitPointerLock?.();$('resultTitle').textContent=win?'VICTORY':'DEFEAT';$('resultTitle').className='result-title '+(win?'win':'loss');$('resultDesc').textContent=win?'Rival chassis disabled. Arena secured.':'Your frame is down. Reboot and take the arena back.';$('result').style.display='grid';}

