function showEnd(win){state.ended=true;state.running=false;document.exitPointerLock?.();$('resultTitle').textContent=win?'VICTORY':'DEFEAT';$('resultTitle').className='result-title '+(win?'win':'loss');$('resultDesc').textContent=win?'Rival chassis disabled. Arena secured.':'Your frame is down. Reboot and take the arena back.';$('result').style.display='grid';}
const forwardOf=(yaw)=>new THREE.Vector3(Math.sin(yaw),0,Math.cos(yaw));
function damage(who,amount){if(!who.alive)return;if(who===player&&who.invuln>0)return;if(who===player&&who.shieldTime>0)amount*=.28;who.hp=Math.max(0,who.hp-amount);who.invuln=who===player?.14:0;setHp(who);state.lastDamage=0;if(who===enemy){player.charge=Math.min(100,player.charge+amount*.55);$('charge').textContent=Math.floor(player.charge)+'%';$('ultBox').classList.toggle('ready',player.charge>=100);$('hitmarker').style.opacity='1';setTimeout(()=>$('hitmarker').style.opacity='0',75);}else{state.shake=.18;}
 if(who.hp<=0){who.alive=false;announce(who===enemy?'HOSTILE FRAME DISABLED':'FRAME CRITICAL');setTimeout(()=>showEnd(who===enemy),650);}}
function shootPlayer(now){if(!state.running||!player.alive||state.reloadTimer>0||now-state.lastShot<(state.overdrive>0?.085:.14))return;
 if(player.ammo<=0){state.reloadTimer=1.25;announce('RECHARGING');return;}state.lastShot=now;player.ammo--;updateHeroUI();
 raycaster.setFromCamera(new THREE.Vector2(0,0),camera);const origin=player.model.muzzle.getWorldPosition(new THREE.Vector3());const hits=raycaster.intersectObject(enemy.model.root,true);let target=raycaster.ray.at(65,new THREE.Vector3());
 if(hits.length){target=hits[0].point;damage(enemy,state.hero==='striker'?26:22);impact(target,0x71edff);}else{const plane=new THREE.Plane(new THREE.Vector3(0,1,0),-1.2);raycaster.ray.intersectPlane(plane,target);if(!target||target.distanceTo(origin)>65)target=raycaster.ray.at(45,new THREE.Vector3());impact(target,0x4ab6c6);}
 tracer(origin,target,state.hero==='striker'?0xffa35e:0x76edff);
}
function shootEnemy(){if(!enemy.alive||!player.alive)return;const from=enemy.model.muzzle.getWorldPosition(new THREE.Vector3()),to=player.pos.clone().add(new THREE.Vector3(0,1.3,0));const dist=from.distanceTo(to);if(dist>31)return;
 const spread=dist<9?.08:.2;to.x+=(Math.random()-.5)*spread*dist;to.y+=(Math.random()-.5)*spread*dist;to.z+=(Math.random()-.5)*spread*dist;tracer(from,to,0xff8653);
 if(Math.random()<Math.max(.25,.79-dist*.012))damage(player,enemy.stun>0?4:9);
