const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.connectOverCDP('http://127.0.0.1:9223');
 const context=browser.contexts()[0];
 const page=context.pages()[0];
 const errors=[];
 page.on('pageerror',e=>errors.push(e.message));
 page.on('console',m=>{if(m.type()==='error')errors.push('console: '+m.text())});
 await page.setViewportSize({width:1365,height:900});
 await page.goto('http://localhost:3002');
 await page.waitForSelector('#start');
 await page.screenshot({path:'/tmp/opencode/pw/final-intro.png'});
 await page.locator('#start').click();
 await page.waitForTimeout(1700);
 const desktopTimer=await page.locator('#timer').innerText();
 await page.screenshot({path:'/tmp/opencode/pw/final-game.png'});
 await page.setViewportSize({width:390,height:844});
 await page.reload();
 await page.waitForSelector('#start');
 const touchVisible=await page.locator('#touchfire').isVisible();
 await page.screenshot({path:'/tmp/opencode/pw/final-mobile-intro.png'});
 await page.locator('#start').click();
 await page.waitForTimeout(1200);
 const mobileTimer=await page.locator('#timer').innerText();
 await page.screenshot({path:'/tmp/opencode/pw/final-mobile-game.png'});
 console.log(JSON.stringify({desktopTimer,mobileTimer,touchVisible,errors},null,2));
 await browser.close();
 if(errors.length) process.exitCode=1;
})().catch(e=>{console.error(e);process.exit(1)});
