input.command:
node <<'NODE'
const { chromium } = require('/home/runner/.local/share/omgithub-playwright/node_modules/playwright-core');
(async()=>{
 const browser=await chromium.connectOverCDP('http://127.0.0.1:9223');
 const page=browser.contexts()[0].pages()[0];
 const errors=[];page.on('pageerror',e=>errors.push(e.message));
 await page.setViewportSize({width:390,height:844});await page.goto('http://localhost:3002');
 await page.locator('#start').click();
 for(let i=0;i<5;i++){await page.waitForTimeout(1000);console.log('timer',i+1,await page.locator('#timer').innerText());}
 await page.screenshot({path:'/tmp/opencode/pw/final-mobile-game-2.png'});
 console.log('errors',errors);
 await browser.disconnect();
})().catch(e=>{console.error(e);process.exit(1)});
NODE

